{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "Ziprasidone, the highest-transfer analogue, had an absolute oral bioavailability of 60 ± 23% for a 20 mg capsule in healthy subjects in the fed state, directly supporting F ≥20% under the query's fed condition.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Trazodone showed an absolute oral bioavailability of 63% versus IV in fasted volunteers, supporting high systemic availability for a related heterocyclic oral drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C47"],
      "claim": "In humans, DPP-4 inhibitors are well absorbed with oral bioavailability of 75–87% and are not significantly influenced by food, supporting high F for a small heterocyclic oral drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Urapidil had an absolute oral bioavailability of 78% after a 30 mg oral solution in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Ondansetron had an absolute oral bioavailability of 75% after an 8 mg oral dose, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Eltrombopag had an estimated oral bioavailability of at least 52% after a single 75 mg oral dose, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "TFMPP showed low bioavailability inferred from <1% urinary recovery after a 60 mg oral dose, providing contradictory evidence.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C03"],
      "claim": "Brexanolone had <5% oral bioavailability in humans, providing contradictory evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Multiple high-transfer analogues with absolute oral bioavailability values of 52–87%, including fed-state ziprasidone at ~60%, support F ≥20%. The query is a small neutral pyrazolone consistent with complete absorption, and the two low-F analogues are outweighed by the higher-scoring and more numerous high-F measurements.",
  "evidence_gaps": [
    "No direct query bioavailability measurement is present; prediction relies on transferable analogues.",
    "Fed-state-specific absolute F data are limited; most supportive analogues were studied fasted or without food specification, though food effects on extent are generally modest for these drugs."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

